// energy/degradation sketch for: PyBaMM
let c = 1.0; const samples = [];
for (let i = 0; i < 663; i++) { c *= 0.99965; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 663, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

